 [Fact] public async Task Unmatched_tax_journal_is_visible_and_blocks_finalization()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c);var doc=(Guid)(await S("INSERT INTO platform.documents(company_id,document_type,business_date,created_by) VALUES(@company,'BAS_TEST',@date,@actor) RETURNING id",("company",db.Company),("date",await Today()),("actor",db.Actor)))!;await using(var session=await db.SessionAsync()){await Sql.RowsAsync(session,"SELECT accounting.post_journal(@doc,1,'BAS_TEST',@date,'Unmatched GST',jsonb_build_array(jsonb_build_object('accountId',(SELECT input_account_id FROM accounting.purchase_gst_entries WHERE company_id=core.current_company() LIMIT 1),'debit',1),jsonb_build_object('accountId',@expense,'credit',1)))",default,("doc",doc),("date",await Today()),("expense",b.Expense));await session.Transaction.CommitAsync();}var r=await Report(c);Assert.Equal("UNRECONCILED",r.GetProperty("status").GetString());Assert.Equal(-1,T(r,"unreconciledDifference"));var p=await CreatePeriod(c);await Expect(await Action(c,Id(p)),HttpStatusCode.Conflict);}
 [Fact] public async Task Period_snapshots_lodgement_reopening_and_amendments_preserve_history()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Invoice(c);var p=await CreatePeriod(c);var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var sid=f.GetProperty("snapshotId").GetGuid();var first=await Get(c,$"/accounting/bas-snapshots/{sid}");Assert.Equal(110,T(first.GetProperty("report"),"G1"));await Expect(await Action(c,Id(p),"record-lodgement",2,lodged:await Today()),HttpStatusCode.OK);await Expect(await Action(c,Id(p),"reopen",3),HttpStatusCode.OK);await Invoice(c);var next=await Expect(await Action(c,Id(p),version:4),HttpStatusCode.OK);Assert.NotEqual(sid,next.GetProperty("snapshotId").GetGuid());var history=await Get(c,$"/accounting/bas-periods/{Id(p)}/history");Assert.Equal(2,history.GetProperty("snapshots").GetArrayLength());Assert.Equal(4,history.GetProperty("events").GetArrayLength());Assert.Equal(first.GetRawText(),(await Get(c,$"/accounting/bas-snapshots/{sid}")).GetRawText());}
