 {await using var api=new TestApi(db);using var c=api.Authenticated();for(var n=0;n<2;n++){var(d,o,l)=await Order(c,"NON_CASH",5.5m,1);await InvoiceOrder(c,o,l,1);}var r=await Report(c);Assert.Equal(1.1m,T(r,"1A"));Assert.Equal(1,D(r.GetProperty("wholeDollarLabels").GetProperty("1A")));Assert.Equal(12,D(r.GetProperty("wholeDollarLabels").GetProperty("G1")));}
 [Fact] public async Task Prior_period_supplier_credit_uses_increasing_adjustment_label()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c,(await Today()).AddDays(-1));await Expect(await Send(c,HttpMethod.Post,$"/supplier-bills/{b.Bill}/amount-credits",new SupplierAmountCreditInput(Code(),"Correction",[new(b.Line,20,2,"Credit")])),HttpStatusCode.Created);var r=await Report(c);Assert.Equal(2,T(r,"1A"));Assert.Equal(0,T(r,"1B"));Assert.Equal("READY",r.GetProperty("status").GetString());}
 [Fact] public async Task Same_period_cash_invoice_requires_reopening_even_when_return_tax_is_unchanged()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var(d,o,l)=await Order(c,"CASH");var r=await Expect(await Receipt(c,d.Customer,24.2m,orderLine:l),HttpStatusCode.Created);var p=await CreatePeriod(c);var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var frozen=await Get(c,$"/accounting/bas-snapshots/{f.GetProperty("snapshotId").GetGuid()}");
 // Invoice and application change accrual GST/advance clearing in this same period, so reopen is mandatory.
 await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{o}/invoices",new InvoiceInput([new(l,2)],"Work completed"),(await Get(c,$"/sales-orders/{o}/invoiceable")).GetProperty("version").GetInt64()),HttpStatusCode.Conflict);
 Assert.Equal(24.2m,T(frozen.GetProperty("report"),"G1"));await Expect(await Action(c,Id(p),"reopen",2),HttpStatusCode.OK);var i=await InvoiceOrder(c,o,l);await Expect(await Apply(c,Advance(r),InvoiceLine(i),24.2m),HttpStatusCode.Created);Assert.Equal(24.2m,T(await Report(c),"G1"));Assert.Equal(2.2m,T(await Report(c),"1A"));}
 [Theory][InlineData(true)][InlineData(false)]
 public async Task Finalization_and_money_posting_serialize_in_both_orders(bool finalFirst)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Bill(c,basis:"CASH");var p=await CreatePeriod(c);await using var session=await db.SessionAsync();
 if(finalFirst){await Sql.RowsAsync(session,"SELECT accounting.bas_transition(@id,1,'FINALIZED',@ref,'Review',NULL)",default,("id",Id(p)),("ref",Code()));var posting=Send(c,HttpMethod.Post,$"/suppliers/{b.Supplier}/payments",new SupplierPaymentInput(55,"BANK_TRANSFER",Code(),Allocations:[new(b.Line,55)]));await Task.Delay(100);Assert.False(posting.IsCompleted);await session.Transaction.CommitAsync();await Expect(await posting,HttpStatusCode.Conflict);Assert.Equal(0,T(await Report(c),"1B"));}
 else{await Sql.RowsAsync(session,"SELECT purchase.post_supplier_payment(@supplier,55,0,'BANK_TRANSFER',@reference,NULL,'BAS transaction',jsonb_build_array(jsonb_build_object('billLineId',@line,'amount',55)))",default,("supplier",b.Supplier),("reference",Code()),("line",b.Line));var finishing=Action(c,Id(p));await Task.Delay(100);Assert.False(finishing.IsCompleted);await session.Transaction.CommitAsync();var f=await Expect(await finishing,HttpStatusCode.OK);var frozen=await Get(c,$"/accounting/bas-snapshots/{f.GetProperty("snapshotId").GetGuid()}");Assert.Equal(5,T(frozen.GetProperty("report"),"1B"));}}
 [Fact] public async Task Failed_audit_rolls_back_snapshot_control_and_idempotency_for_retry()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var p=await CreatePeriod(c);var key=Code();await S($"CREATE FUNCTION accounting.test_bas_audit_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.company_id='{db.Company}'::uuid AND NEW.action='accounting.bas_finalize' THEN RAISE EXCEPTION 'Injected BAS failure' USING ERRCODE='HR422';END IF;RETURN NEW;END $$;CREATE TRIGGER test_bas_audit_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_bas_audit_failure()");try{await Expect(await Action(c,Id(p),key:key),HttpStatusCode.UnprocessableEntity);Assert.Empty((await Get(c,$"/accounting/bas-periods/{Id(p)}/history")).GetProperty("snapshots").EnumerateArray());Assert.Equal("OPEN",(await Get(c,$"/accounting/bas-periods/{Id(p)}")).GetProperty("state").GetString());}finally{await S("DROP TRIGGER test_bas_audit_failure ON platform.audit_events;DROP FUNCTION accounting.test_bas_audit_failure()");}await Expect(await Action(c,Id(p),key:key),HttpStatusCode.OK);}

 [Fact] public async Task Historical_cash_advance_application_is_allowed_when_frozen_financial_values_are_unchanged()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var(d,o,l)=await Order(c,"CASH");var day=(await Today()).AddDays(-1);var r=await Expect(await Receipt(c,d.Customer,24.2m,orderLine:l,date:day),HttpStatusCode.Created);var p=await CreatePeriod(c,(await Input())with{From=day,To=day.AddDays(1)});var f=await Expect(await Action(c,Id(p)),HttpStatusCode.OK);var sid=f.GetProperty("snapshotId").GetGuid();var before=await Get(c,$"/accounting/bas-snapshots/{sid}");var i=await InvoiceOrder(c,o,l);await Expect(await Apply(c,Advance(r),InvoiceLine(i),24.2m),HttpStatusCode.Created);var historical=await Report(c,day,day.AddDays(1));Assert.Equal(24.2m,T(historical,"G1"));Assert.Equal(2.2m,T(historical,"1A"));Assert.Equal("RECONCILED",historical.GetProperty("ledgerStatus").GetString());Assert.Equal(before.GetRawText(),(await Get(c,$"/accounting/bas-snapshots/{sid}")).GetRawText());}
 [Fact] public async Task Negative_G1_is_visible_requires_review_and_cannot_be_finalized()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var(d,o,l)=await Order(c,"CASH");var r=await Expect(await Receipt(c,d.Customer,24.2m,orderLine:l,date:(await Today()).AddDays(-1)),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/customers/{d.Customer}/refunds",new CustomerRefundInput(24.2m,Code(),"Refund",AdvanceId:Advance(r))),HttpStatusCode.Created);var b=await Report(c);Assert.Equal(-24.2m,T(b,"G1"));Assert.Equal(2.2m,T(b,"1B"));Assert.Equal("REVIEW_REQUIRED",b.GetProperty("status").GetString());var p=await CreatePeriod(c);await Expect(await Action(c,Id(p)),HttpStatusCode.Conflict);}
